'use strict';

/**
 * /v1/auth — the SDK handles the Basic → Bearer token exchange for you
 * automatically on every request, so you normally won't need to call
 * these directly. They're exposed for advanced use cases.
 */
class Auth {
  constructor(client) {
    this.client = client;
  }

  /**
   * Get information about the currently authenticated context
   * (merchant, environment, scopes).
   */
  me() {
    return this.client.request('GET', '/v1/auth/me');
  }

  /**
   * Force a fresh token exchange right now (normally handled automatically).
   */
  refreshToken() {
    this.client._token = null;
    this.client._tokenExpiresAt = 0;
    return this.client._ensureToken();
  }
}

module.exports = Auth;
